/// <summary>
/// MPJ-3746 - KScerri - 07/05/2021
/// The <c>METPayTermTable_Extension</c> class extension required to add additional logic to payment due date calculation
/// </summary>
[ExtensionOf(tableStr(PaymTerm))]
public final class METPayTermTable_Extension
{
}

Method.Source:
    /// <summary>
    /// MPJ-3746 - KScerri - 16/06/2021
    /// </summary>
    /// <param name = "_transDate">TransDate</param>
    /// <param name = "_calledFromAOS">calledFromAos</param>
    /// <returns>duedate</returns>
    protected DueDate calculateDueDateFromPaymMethod(TransDate _transDate, boolean _calledFromAOS)
    {
        DueDate metDueDate, metTempDate;

        metDueDate = next calculateDueDateFromPaymMethod(_transDate, _calledFromAOS);
        
        if (this.METCutOffDays > 0)
        {
            if (dayofmth(_transDate) > this.METCutOffDays)
            {
                metTempDate = nextMth(_transDate);
                metDueDate = mkDate(this.METCutOffDays, mthOfYr(metTempDate), Year(metTempDate));
            }
            else
            {
                metDueDate = mkDate(this.METCutOffDays, mthOfYr(_transDate), Year(_transDate));
            }
        }

        return metDueDate;
    }
